    // -- GRACE PERIOD (attribution window) -------------------
    // Hour boundaries are anchored to the shift start MINUTE, not to :00. The window
    // runs for 10 minutes after each boundary, so a 20:00 start gives :00-:10, a 20:15
    // start gives :15-:25 and a 19:30 start gives :30-:40.
    const GRACE_WINDOW_MINUTES=10;
    function minutesIntoShiftHour(date){const{shiftStart}=getShiftTimeWindows();return((date.getMinutes()-shiftStart.getMinutes())+60)%60}
    function isInGraceWindow(date){return minutesIntoShiftHour(date)<GRACE_WINDOW_MINUTES}
    function getGraceWindowLabel(){
        const{shiftStart}=getShiftTimeWindows();const s=shiftStart.getMinutes();
        const pad=n=>String(n).padStart(2,'0');
        return':'+pad(s)+'-:'+pad((s+GRACE_WINDOW_MINUTES)%60)}
    function updateAttributionModalText(date,doorNum){
        const el=byId('attribution-window-text');if(!el)return;
        const t=date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
        el.textContent=(doorNum!=null?'Door '+doorNum:'Trailer')+' completed at '+t+'. Assign completion to previous hour or current hour.'}
    function populateUnloaderSelect(){const ids=['select-unloader','edit-select-unloader','edit-active-unloader','filter-unloader-select','req-unloader-select','manual-unloader'];ids.forEach(id=>{const el=byId(id);if(!el)return;const isFilter=id==='filter-unloader-select';el.innerHTML=isFilter?'<option value="All">All Unloaders</option>':'<option value="" selected>Unassigned</option>';teamNamesSorted.forEach(name=>{const opt=document.createElement('option');opt.value=name;opt.innerText=name;el.appendChild(opt)});if(!isFilter)el.innerHTML+='<option value="Custom">Custom / Other</option>'})}
