    function confirmManualAdd(){let id=manualType==='Wally'?byId('manual-wally-id').value:byId('manual-trailer-id').value;if(!id)return alert("Please enter an ID");id=id.toUpperCase();let account='',cpuOpts=[];if(manualType==='CPU'){account=byId('manual-account-id').value.toUpperCase();if(byId('manual-chk-hott').checked)cpuOpts.push('HOTT');if(byId('manual-chk-recycle').checked)cpuOpts.push('RECYCLE');if(byId('manual-chk-gv').checked)cpuOpts.push('GV')}let unl=byId('manual-unloader').value;if(unl==='Custom'){unl=byId('manual-custom-unloader').value.trim();if(!unl)return alert("Please enter custom unloader name");unl=unl.toLowerCase().split(' ').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ')}if(!unl)unl="Unassigned";const selectedHour=parseInt(byId('manual-hour-select').value),now=Date.now(),{shiftStart}=getShiftTimeWindows(),targetEffective=shiftStart.getTime()+(selectedHour-1)*3600000;let offset=now-targetEffective;if(offset<0)offset=0;const logEntry={door:0,id:id,account:account,type:manualType,unloader:unl,assistants:[],start:now-15*60000,end:now,dateKey:dateKeyFromTs(now),shiftKey:currentShiftKey(),duration:15*60000,durationMinutes:15,statOffset:offset,logId:Date.now().toString(36)+Math.random().toString(36).substr(2),duplicate:false,completionHour:getCompletionHour(now-offset),cpuOptions:cpuOpts,status:'completed',manual:true};historyLog.unshift(logEntry);sendToWebhook(logEntry,'end');saveHistory();closeModal('manual-add-modal');renderDashboard();if(byId('tab-logs').classList.contains('active'))renderLogs();showSaveToast()}
    function switchTab(tabId,btn){document.querySelectorAll('.tab-content').forEach(el=>el.classList.remove('active'));byId(`tab-${tabId}`).classList.add('active');document.querySelectorAll('.tab-btn').forEach(el=>{el.classList.remove('active');el.setAttribute('aria-selected','false')});if(btn){btn.classList.add('active');btn.setAttribute('aria-selected','true')}else{const icons=document.querySelectorAll('.tab-btn'),idx=['dashboard','active','logs','hours','tools','settings'].indexOf(tabId);if(idx>=0){icons[idx].classList.add('active');icons[idx].setAttribute('aria-selected','true')}}if(tabId==='dashboard')renderDashboard();if(tabId==='active')renderActiveTab();if(tabId==='logs'){currentVisibleLogs=50;renderLogs()}if(tabId==='hours')htRenderAll();const fab=document.getElementById('ht-fab-btn');if(fab){fab.classList.toggle('visible',tabId==='hours');}}
