    function updateStats(){const{thisHourStart,thisHourEnd,lastHourStart,lastHourEnd}=getShiftTimeWindows();let tw=0,tc=0,hw=0,lhw=0;thisShiftLogs().forEach(l=>{if(!l.completionHour)return;const t=l.end-(l.statOffset||0);if(l.type==='Wally'){tw++;if(t>=thisHourStart.getTime()&&t<thisHourEnd.getTime())hw++;else if(t>=lastHourStart.getTime()&&t<lastHourEnd.getTime())lhw++}else if(l.type==='CPU')tc++});byId('stat-total-wally').innerText=tw;byId('stat-total-cpu').innerText=tc;byId('stat-hour-wally').innerText=hw;byId('stat-last-wally').innerText=lhw;const ov=byId('stat-total-overall');if(ov)ov.innerText=tw+tc;}
