    function renderLogs(){const list=byId('logs-list');if(!list)return;const filterDisplay=byId('active-filter-display'),filterText=byId('filter-text-display'),sVal=byId('log-search').value.trim().toUpperCase();activeLogFilter.search=sVal;const{thisHourStart,thisHourEnd,lastHourStart,lastHourEnd}=getShiftTimeWindows();filteredLogsCache=[];historyLog.forEach((l,masterIndex)=>{if(activeLogFilter.date!=='All'&&l.dateKey!==activeLogFilter.date)return;if(activeLogFilter.door!=='All'&&l.door!=activeLogFilter.door)return;if(activeLogFilter.unloader!=='All'&&l.unloader!==activeLogFilter.unloader)return;if(activeLogFilter.type!=='All'&&l.type!==activeLogFilter.type)return;if(activeLogFilter.search){const nObj=getNoteObj(l.id);const noteText=nObj?(nObj.tags.map(t=>t.value).join(' ')+' '+(nObj.text||'')).toUpperCase():'';if(!l.id.includes(sVal)&&!(l.account||'').includes(sVal)&&String(l.door)!=sVal&&!noteText.includes(sVal))return}if(activeLogFilter.timeRange!=='All'){const t=l.end-(l.statOffset||0);if(activeLogFilter.timeRange==='ThisHour'&&(t<thisHourStart.getTime()||t>=thisHourEnd.getTime()))return;if(activeLogFilter.timeRange==='LastHour'&&(t<lastHourStart.getTime()||t>=lastHourEnd.getTime()))return}filteredLogsCache.push({log:l,masterIndex:masterIndex})});const isFiltering=Object.values(activeLogFilter).some(v=>v!=='All'&&v!=='');if(filterDisplay){filterDisplay.style.display=isFiltering?'flex':'none';if(isFiltering){const p=[];if(activeLogFilter.date!=='All')p.push(activeLogFilter.date);if(activeLogFilter.door!=='All')p.push("Door "+activeLogFilter.door);if(activeLogFilter.unloader!=='All')p.push(activeLogFilter.unloader);if(activeLogFilter.type!=='All')p.push(activeLogFilter.type);if(activeLogFilter.search)p.push(`"${activeLogFilter.search}"`);filterText.innerText=p.join(' + ')}}list.innerHTML='';currentVisibleLogs=50;renderLogBatch();if(statsVisible)calculateAndRenderStats();if(hourlyVisible)calculateAndRenderHourlyStats()}
    function renderLogBatch(){const list=byId('logs-list'),loadMore=byId('logs-load-more');if(filteredLogsCache.length===0){list.innerHTML='<div style="text-align:center;color:var(--text-muted);margin-top:20px;">No logs found.</div>';loadMore.style.display='none';return}const frag=document.createDocumentFragment(),batch=filteredLogsCache.slice(list.children.length,currentVisibleLogs);batch.forEach(item=>{const l=item.log,idx=item.masterIndex,card=document.createElement('div');card.className='log-card';const dur=Math.round(l.duration/60000);const unloadDur=l.unloadDurationMinutes!=null?l.unloadDurationMinutes:dur;const dwell=l.dwellMinutes||0;let statusPill='';if(l.status==='moved')statusPill=`<span class="log-tag tag-gray"><i class="ph ph-arrows-left-right"></i> ${l.moveDest}</span>`;else if(l.status==='incomplete')statusPill=`<span class="log-tag tag-red"><i class="ph ph-x-circle"></i> Incomplete</span>`;else{statusPill=`<span class="log-tag tag-black">${l.type}</span>`;if(l.duplicate)statusPill+=` <span class="log-tag tag-red">DUP</span>`;if(l.type==='CPU'&&l.cpuOptions&&l.cpuOptions.length>0)l.cpuOptions.forEach(opt=>{statusPill+=` <span class="log-tag tag-gray">${opt}</span>`})}statusPill+=`<span class="log-tag" style="background:#fff;border:1px solid var(--border);">${l.completionHour?getHourText(l.completionHour):'--'}</span>`;if(l.manual)statusPill+=` <span class="log-tag tag-gray"><i class="ph ph-pencil-simple-line"></i> Manual</span>`;if(l.idleBeforeMinutes!=null&&l.idleBeforeMinutes>=0)statusPill+=` <span class="log-tag" style="background:var(--accent-blue-bg);color:var(--accent-blue);"><i class="ph ph-timer"></i> Idle: ${l.idleBeforeMinutes}m</span>`;const timeRange=`${new Date(l.start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} - ${new Date(l.end).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;const hasN=l.type==='Wally'&&noteHasContent(l.id);const noteIcon=l.type==='Wally'?`<button class="note-icon-btn ${hasN?'has-note':''}" onclick="openNoteModal('${l.id}','log')"><i class="ph ph-note${hasN?'-pencil':''}"></i></button>`:'';const dwellStr=dwell>0?`<div class="log-footer-item" style="color:var(--accent-orange);"><i class="ph ph-hourglass"></i> Dwell ${dwell}m</div>`:'';card.innerHTML=`<div class="log-info"><div class="log-header-row"><span class="log-door-pill" onclick="viewDoorLogs(${l.door})">Door ${l.door}</span><div class="log-title">${l.id}${noteIcon}<span class="log-account">${l.account?l.account:''}</span></div></div><div class="log-tags-row">${statusPill}</div><div class="log-footer-row"><div class="log-footer-item"><i class="ph ph-user"></i> ${l.unloader}</div><div class="log-footer-item"><i class="ph ph-clock"></i> ${timeRange}</div>${dwellStr}</div></div><div class="log-right-col"><div style="text-align:right;"><div class="log-duration">${unloadDur}<span style="font-size:14px;font-weight:700;">m</span></div><div class="log-duration-label">Unload</div>${dwell>0?`<div style="font-size:10px;color:var(--text-muted);font-weight:600;margin-top:2px;">${dur}m Door</div>`:''}</div><div class="log-actions-row">${(Date.now()-l.end<120000&&!demoActive&&l.status==='completed'&&!l.manual)?`<button class="log-mini-btn" onclick="revertLog(${idx})"><i class="ph ph-arrow-u-up-left"></i></button>`:''}<button class="log-mini-btn" onclick="openEditLogModal(${idx})"><i class="ph ph-pencil-simple"></i></button></div></div>`;frag.appendChild(card)});list.appendChild(frag);loadMore.style.display=(currentVisibleLogs<filteredLogsCache.length)?'block':'none'}
    function loadMoreLogs(){currentVisibleLogs+=50;renderLogBatch()}
    function revertLog(i){const l=historyLog[i];if(!l||l.manual||!doors[l.door]||(Date.now()-l.end>120000&&!demoActive)||doors[l.door].status!=='empty')return alert("Cannot revert");doors[l.door]={status:'active',start:l.start,id:l.id,account:l.account,type:l.type,unloader:l.unloader,unavailable:false,lastCompletionTime:null,cpuOptions:l.cpuOptions||[],assignments:[{name:l.unloader,start:l.start,end:null}],logId:l.logId};historyLog.splice(i,1);saveDoors();saveHistory();renderDashboard();renderLogs();updateTabBadges()}
    function openEditLogModal(i){const l=historyLog[i];byId('edit-log-index').value=i;byId('edit-input-id').value=l.id;const sel=byId('edit-select-unloader');sel.innerHTML='<option value="">Unassigned</option>';teamNamesSorted.forEach(n=>{const o=document.createElement('option');o.value=n;o.innerText=n;sel.appendChild(o)});if(l.unloader&&l.unloader!=='Unassigned'&&!teamNamesSorted.includes(l.unloader)){const o=document.createElement('option');o.value=l.unloader;o.innerText=l.unloader+' (not on team)';sel.appendChild(o)}sel.value=l.unloader;setEditType(l.type);const opts=l.cpuOptions||[];byId('edit-log-chk-hott').checked=opts.includes('HOTT');byId('edit-log-chk-recycle').checked=opts.includes('RECYCLE');byId('edit-log-chk-gv').checked=opts.includes('GV');byId('edit-completion-hour').value=l.completionHour;byId('edit-log-modal').style.display='flex'}
    function confirmLogEdit(){const i=parseInt(byId('edit-log-index').value),id=byId('edit-input-id').value.toUpperCase(),unl=byId('edit-select-unloader').value,type=byId('edit-log-modal').dataset.type;let cpuOpts=[];if(type==='CPU'){if(byId('edit-log-chk-hott').checked)cpuOpts.push('HOTT');if(byId('edit-log-chk-recycle').checked)cpuOpts.push('RECYCLE');if(byId('edit-log-chk-gv').checked)cpuOpts.push('GV')}const newHour=parseInt(byId('edit-completion-hour').value),{shiftStart}=getShiftTimeWindows(),newEnd=shiftStart.getTime()+(newHour*3600000)-5*60000,start=historyLog[i].start;const oldId=historyLog[i].id;historyLog[i].id=id;historyLog[i].unloader=unl;historyLog[i].type=type;historyLog[i].cpuOptions=cpuOpts;historyLog[i].end=newEnd;historyLog[i].duration=newEnd-start;historyLog[i].durationMinutes=Math.round(historyLog[i].duration/60000);historyLog[i].completionHour=newHour;historyLog[i].dateKey=dateKeyFromTs(newEnd);historyLog[i].statOffset=0;if(wallyNotes[oldId]&&oldId!==id){wallyNotes[id]=wallyNotes[oldId];delete wallyNotes[oldId];saveNotes()}saveHistory();sendToWebhook(historyLog[i],'end');closeModal('edit-log-modal');renderLogs();renderDashboard();showSaveToast()}
    function openExportModal(){byId('export-modal').style.display='flex'}
    function exportLogsCSV(){closeModal('export-modal');let csv="Type,ID,Account,Door,Unloader,Duration(mins),StartTime,EndTime,StartHour,EndHour,Duplicate,Hour,Options,Status,Manual,MoveDest\n";historyLog.forEach(l=>{const opts=(l.cpuOptions||[]).join(';');csv+=`${l.type},${l.id},${l.account||''},${l.door},${l.unloader},${Math.round(l.duration/60000)},${new Date(l.start).toLocaleString()},${new Date(l.end).toLocaleString()},${new Date(l.start).getHours()},${new Date(l.end).getHours()},${l.duplicate?'Yes':'No'},${l.completionHour||''},${opts},${l.status||'completed'},${l.manual?'Yes':'No'},${l.moveDest||''}\n`});const a=document.createElement('a');a.href=window.URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='wally-logs.csv';a.click()}
    function exportLogsPDF(){closeModal('export-modal');if(!window.jspdf)return alert("PDF library loading.");const doc=new window.jspdf.jsPDF(),now=new Date();doc.setFontSize(18);doc.text(`PS9 Wally Tracker Report - ${now.toLocaleDateString()}`,14,20);doc.setFontSize(12);doc.text(`Generated: ${now.toLocaleTimeString()}`,14,30);const stats={};historyLog.forEach(l=>{if(!l.completionHour)return;const n=l.unloader;if(!stats[n])stats[n]={w:0,c:0,t:0};if(l.type==='Wally')stats[n].w++;else if(l.type==='CPU')stats[n].c++;stats[n].t++});doc.autoTable({startY:45,head:[['Name','Wally','CPU','Total']],body:Object.entries(stats).sort((a,b)=>b[1].t-a[1].t).map(([n,d])=>[n,d.w,d.c,d.t])});const logsBody=historyLog.map(l=>{let typeStr=l.type+(l.duplicate?' (DUP)':'');if(l.status==='moved')typeStr=`MOVED: ${l.moveDest}`;else if(l.status==='incomplete')typeStr='INCOMPLETE';else if(l.type==='CPU'&&l.cpuOptions&&l.cpuOptions.length>0)typeStr+=`\n${l.cpuOptions.join(',')}`;return[new Date(l.end).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),l.door,typeStr,l.id,l.unloader,Math.round(l.duration/60000)+"m",l.completionHour?getHourText(l.completionHour):'--']});doc.autoTable({startY:doc.lastAutoTable.finalY+15,head:[['Time','Door','Type','ID','Unloader','Duration','Hour']],body:logsBody});doc.save(`wally-report-${now.toISOString().split('T')[0]}.pdf`)}
    function setEditType(t){byId('edit-opt-wally').classList.toggle('selected',t==='Wally');byId('edit-opt-cpu').classList.toggle('selected',t==='CPU');byId('edit-log-modal').dataset.type=t;const c=byId('edit-log-options-container');if(c)c.style.display=(t==='CPU')?'block':'none'}
    function setLaborTimeNow(){const n=new Date();byId('edit-active-labor-time').value=n.getHours().toString().padStart(2,'0')+':'+n.getMinutes().toString().padStart(2,'0');}
    function openMoveMenu(){closeModal('active-detail-modal');byId('move-menu-modal').style.display='flex'}
